/* ============================================================
   PORTFOLIO JS
   - Seamless dual-video gold loop background
   - Scroll progress bar
   - Nav active states + shrink on scroll
   - Side dot active states
   - Reveal animations (IntersectionObserver)
   - Count-up numbers
   - Contact form (Web3Forms)
   ============================================================ */

/* ── 1. INJECT VIDEO BACKGROUND ──────────────────────────── */
(function() {
  const wrap = document.createElement('div');
  wrap.id = 'video-bg';
  wrap.innerHTML =
    '<video id="vid1" autoplay muted playsinline webkit-playsinline></video>' +
    '<video id="vid2" autoplay muted playsinline webkit-playsinline></video>' +
    '<div class="vov"></div>';
  document.body.insertBefore(wrap, document.body.firstChild);

  const src = 'data:video/mp4;base64,';
  const v1  = document.getElementById('vid1');
  const v2  = document.getElementById('vid2');
  v1.src = src;  v2.src = src;
  v1.load(); v2.load();

  // Seamless crossfade loop
  // Two videos ping-pong: while one plays, the other waits at 0
  // 0.5s before the active one ends, fade to the standby
  let active  = v1, standby = v2;
  let fading  = false;

  v1.style.cssText = 'opacity:1;transition:opacity 0.5s ease';
  v2.style.cssText = 'opacity:0;transition:opacity 0.5s ease';

  function startLoop(v) {
    v.play().catch(() => {});
    v.addEventListener('timeupdate', function check() {
      if (!fading && v.duration && v.currentTime >= v.duration - 0.5) {
        fading = true;
        standby.currentTime = 0;
        standby.play().catch(() => {});
        // Crossfade
        active.style.opacity  = '0';
        standby.style.opacity = '1';
        setTimeout(function() {
          var tmp = active;
          active  = standby;
          standby = tmp;
          fading  = false;
          // Remove listener from old active, add to new
          startLoop(active);
          tmp.removeEventListener('timeupdate', check);
        }, 600);
      }
    });
  }

  function tryStart() {
    if (v1.readyState >= 2 && v2.readyState >= 2) {
      startLoop(v1);
    }
  }

  v1.addEventListener('canplay', tryStart);
  v2.addEventListener('canplay', tryStart);
  // Fallback — try after 1s even if not fully ready
  setTimeout(function() {
    if (v1.paused) { v1.play().catch(()=>{}); startLoop(v1); }
  }, 1000);
})();

/* ── 2. SCROLL PROGRESS BAR ───────────────────────────────── */
function updateProgress() {
  var scrolled = window.scrollY;
  var total    = document.documentElement.scrollHeight - window.innerHeight;
  var pct      = total > 0 ? (scrolled / total * 100).toFixed(2) + '%' : '0%';
  document.getElementById('progress-bar').style.setProperty('--prog', pct);
}
window.addEventListener('scroll', updateProgress, { passive: true });

/* ── 3. NAV SHRINK ON SCROLL ───────────────────────────────── */
var nav = document.getElementById('nav');
window.addEventListener('scroll', function() {
  nav.classList.toggle('scrolled', window.scrollY > 50);
}, { passive: true });

/* ── 4. ACTIVE NAV + SIDE DOTS ─────────────────────────────── */
var sections  = Array.from(document.querySelectorAll('.chapter'));
var navLinks  = Array.from(document.querySelectorAll('.nav-links a'));
var sideDots  = Array.from(document.querySelectorAll('.sdot'));

var sectionIds = sections.map(function(s) { return s.id; });

function setActive(id) {
  navLinks.forEach(function(a) {
    a.classList.toggle('active', a.getAttribute('href') === '#' + id);
  });
  sideDots.forEach(function(d) {
    d.classList.toggle('active', d.getAttribute('href') === '#' + id);
  });
}

var observer = new IntersectionObserver(function(entries) {
  entries.forEach(function(e) {
    if (e.isIntersecting) setActive(e.target.id);
  });
}, { threshold: 0.4 });

sections.forEach(function(s) { observer.observe(s); });

/* ── 5. REVEAL ON SCROLL ────────────────────────────────────── */
var revealObserver = new IntersectionObserver(function(entries) {
  entries.forEach(function(e) {
    if (e.isIntersecting) {
      e.target.classList.add('visible');
      revealObserver.unobserve(e.target);
    }
  });
}, { threshold: 0.15 });

document.querySelectorAll('.reveal-left, .reveal-right, .reveal-up')
  .forEach(function(el) { revealObserver.observe(el); });

/* ── 6. COUNT-UP NUMBERS ────────────────────────────────────── */
function countUp(el) {
  if (el.dataset.done) return;
  el.dataset.done = '1';
  var target = parseInt(el.dataset.count, 10);
  if (isNaN(target)) return;
  var duration = 1400;
  var start    = performance.now();
  function step(now) {
    var p = Math.min((now - start) / duration, 1);
    var ease = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(ease * target);
    if (p < 1) requestAnimationFrame(step);
    else el.textContent = target;
  }
  requestAnimationFrame(step);
}

var countObserver = new IntersectionObserver(function(entries) {
  entries.forEach(function(e) {
    if (e.isIntersecting) {
      e.target.querySelectorAll('.astat-num[data-count]').forEach(countUp);
    }
  });
}, { threshold: 0.4 });

document.querySelectorAll('#about').forEach(function(s) {
  countObserver.observe(s);
});

/* ── 7. YEAR ────────────────────────────────────────────────── */
var yrEl = document.getElementById('yr');
if (yrEl) yrEl.textContent = new Date().getFullYear();

/* ── 8. CONTACT FORM ─────────────────────────────────────────── */
var form = document.getElementById('contactForm');
if (form) {
  form.addEventListener('submit', function(e) {
    e.preventDefault();
    var btn = form.querySelector('button[type="submit"]');
    var err = document.getElementById('formError');
    btn.textContent = 'Sending…';
    btn.disabled = true;

    fetch('https://api.web3forms.com/submit', {
      method: 'POST',
      headers: { 'Accept': 'application/json' },
      body: new FormData(form)
    })
    .then(function(r) { return r.json(); })
    .then(function(d) {
      if (d.success) {
        form.reset();
        btn.textContent = 'Message Sent ✓';
        err.style.cssText = 'color:#ffd700;font-size:.72rem;margin-top:6px';
        err.textContent = '✓ Message received — I\'ll get back to you soon!';
        setTimeout(function() {
          btn.textContent = 'Send Message →';
          err.textContent = '';
        }, 4000);
      } else throw new Error();
    })
    .catch(function() {
      err.style.cssText = 'color:#ff4422;font-size:.72rem;margin-top:6px';
      err.textContent = '✕ Something went wrong — please try again.';
      btn.textContent = 'Send Message →';
    })
    .finally(function() { btn.disabled = false; });
  });
}